/* ---- product page: videos & reels ---- */
function prodVideos(id){const p=prod(id),o=biz(p.bid);const own=(o.media||[]).filter(m=>m.status==='approved'&&(m.tags||[]).includes(id));const pm=(p.media||[]).filter(m=>m.t!=='img');const rows=[...own.map(m=>({m,o})),...pm.map(m=>({m:vidNorm(m,p,o),o}))];if(!rows.length)return '';
 return `<section><h2 style="margin-bottom:8px">${t('Videos & Reels')}</h2><div class="grid auto">${rows.map(({m,o})=>`<div class="card"><button class="art w" style="--h:${m.t==='yt'?0:330};width:100%;border:0;position:relative;cursor:pointer" data-act="openReel" data-id="${m.id}" aria-label="${t('Play')}: ${esc(m.title)}"><span>${m.thumb}</span><span style="position:absolute;inset:0;display:grid;place-items:center;pointer-events:none"><span style="width:52px;height:52px;border-radius:50%;background:rgba(0,0,0,.65);display:grid;place-items:center;color:#fff">${ic('play',22)}</span></span></button><div class="pad" style="padding:10px 12px;display:grid;gap:4px"><b class="small">${esc(m.title)}</b><div class="row wrap-r" style="gap:6px"><span class="badge info">${mLabel(m)}</span><a class="small" href="${esc(extUrl(m))}" target="_blank" rel="noopener">${t('Open in')} ${mLabel(m)}</a></div></div></div>`).join('')}</div></section>`}
function vidNorm(m,p,o){return {...m,cap:m.title,hashtags:[],tags:[p.id],status:'approved',views:m.views||800,likes:m.likes||90,shares:m.shares||10,gained:0,taps:0,thumb:m.thumb||(m.t==='yt'?'▶️':'📷'),dur:m.dur||20,reels:true,gal:true,comments:[],ts:m.ts||Date.now()-3*DAY}}
A.openReel=el=>go('videos-'+el.dataset.id);
const _p3=V.prod;V.prod=id=>{let h=_p3(id);const vs=prodVideos(id);if(vs)h=h.replace('<section><div class="sec" style="margin-top:0">',vs+'<section><div class="sec" style="margin-top:0">');return h};
/* allVideos now also includes product-media videos */
function allVideos(){const out=[];[...D().biz,...D().svc].forEach(o=>(o.media||[]).forEach(m=>out.push({m,o})));D().products.forEach(p=>(p.media||[]).filter(m=>m.t!=='img').forEach(m=>{const o=biz(p.bid);if(o)out.push({m:vidNorm(m,p,o),o})}));return out}
